use std::sync::Arc;
use maho_omo_task::dag_snapshot_payload::dag_updated_payload;
use senpi_task::dag::{manager::{create_dag_manager,DagManagerOptions,DagStartParams},store::{create_dag_file_store,DagStoreConfig,DagStoreOptions},types::DagRunSnapshot};
use serde_json::json;
fn snapshot()->(tempfile::TempDir,DagRunSnapshot) {
    let root=tempfile::tempdir().expect("root"); let store=create_dag_file_store(&DagStoreConfig::new(root.path()),DagStoreOptions::default()).expect("store"); let manager=create_dag_manager(DagManagerOptions { store:Arc::new(store),new_run_id:Some(Arc::new(|| "run".into())),now:Some(Arc::new(|| 1000)),materialize_skills:None,settings:None });
    let definition=senpi_task::dag::graph::DagDefinition { key:"key".into(),name:"release".into(),nodes:vec![senpi_task::dag::graph::DagNodeInput { id:"a".into(),prompt:"work".into(),target:senpi_task::dag::types::DagNodeTarget::Category("quick".into()),label:None,depends_on:None,task_summary:None,description:None,load_skills:None }] }; let run=manager.start(DagStartParams { definition,parent_session_id:"parent".into(),root_session_id:"root".into() }).expect("run").snapshot; (root,run)
}
#[test] fn snapshot_cap_reports_only_actual_overflow() {
    let (_root,run)=snapshot(); let mut runs=(0..256).map(|index| { let mut run=run.clone(); run.run_id=format!("run-{index}"); (run,"updated".into()) }).collect::<Vec<_>>();
    let value=dag_updated_payload("parent",&runs); assert_eq!(value["runs"].as_array().expect("runs").len(),256); assert!(value.get("truncated_runs").is_none()); runs.push((run,"updated".into())); let value=dag_updated_payload("parent",&runs); assert_eq!(value["truncated_runs"],1); assert_eq!(value["runs"].as_array().expect("runs").len(),256); assert_eq!(value["runs"][255]["run_id"],"run-255");
}
#[test] fn wire_payload_is_snake_case_with_absent_optional_node_fields() {
    let (_root,mut run)=snapshot(); let value=dag_updated_payload("parent",&[(run.clone(),"updated".into())]); assert_eq!(value["parent_session_id"],"parent"); assert_eq!(value["runs"][0]["updated_at"],"updated"); assert_eq!(value["runs"][0]["waves"][0]["node_ids"],json!(["a"]));
    for key in ["label","task_id","started_at","completed_at","last_error"] { assert!(value["runs"][0]["nodes"][0].get(key).is_none()); }
    run.nodes[0].label=Some("label".into()); run.nodes[0].task_id=Some("st_a".into()); run.nodes[0].started_at=Some("start".into()); run.nodes[0].completed_at=Some("end".into()); let value=dag_updated_payload("parent",&[(run,"updated".into())]); let node=&value["runs"][0]["nodes"][0]; assert_eq!(node["label"],"label"); assert_eq!(node["task_id"],"st_a"); assert_eq!(node["started_at"],"start"); assert_eq!(node["completed_at"],"end"); assert!(node.get("taskId").is_none());
}
#[test] fn additive_run_and_error_fields_match_desktop_wire_contract() {
    let (_root,mut run)=snapshot(); run.completed_at=Some("done".into()); run.lease_holder_pid=Some(4242); run.amend_history=Some(vec![run.amend_history.clone().unwrap_or_default().into_iter().next().unwrap_or_else(||senpi_task::dag::types::AmendRecord {at:"at".into(),previous_fingerprint:"old".into(),fingerprint:"new".into(),changed_node_ids:vec![],added_node_ids:vec![],invalidated_node_ids:vec![]})]); run.nodes[0].error=Some(senpi_task::dag::types::DagNodeError {code:senpi_task::dag::types::DagNodeErrorCode::TaskError,message:"failed".into(),node_id:Some("a".into()),at:"at".into()});
    let value=dag_updated_payload("parent",&[(run,"updated".into())]); let run=&value["runs"][0]; assert_eq!(run["completed_at"],"done"); assert_eq!(run["amend_count"],1); assert_eq!(run["lease_holder_pid"],4242); assert_eq!(run["nodes"][0]["last_error"],json!({"code":"task_error","message":"failed"}));
}
#[test] fn last_error_omits_node_and_timestamp_metadata(){let(_root,mut run)=snapshot();run.nodes[0].error=Some(senpi_task::dag::types::DagNodeError{code:senpi_task::dag::types::DagNodeErrorCode::TaskCancelled,message:"cancelled".into(),node_id:Some("a".into()),at:"when".into()});let value=dag_updated_payload("parent",&[(run,"updated".into())]);let error=&value["runs"][0]["nodes"][0]["last_error"];assert_eq!(error,&json!({"code":"task_cancelled","message":"cancelled"}));}
#[test] fn empty_amend_history_and_absent_completed_at_and_lease_stay_omitted(){let(_root,mut run)=snapshot();run.amend_history=Some(vec![]);run.completed_at=None;run.lease_holder_pid=None;let payload=dag_updated_payload("parent",&[(run,"updated".into())]);let run=&payload["runs"][0];assert!(run.get("amend_count").is_none());assert!(run.get("completed_at").is_none());assert!(run.get("lease_holder_pid").is_none());}
#[test] fn failed_node_retry_payload_keeps_attempt_and_last_error(){let(_root,mut run)=snapshot();run.nodes[0].attempt=2;run.nodes[0].state=senpi_task::dag::types::DagNodeState::Failed;run.nodes[0].error=Some(senpi_task::dag::types::DagNodeError{code:senpi_task::dag::types::DagNodeErrorCode::TaskError,message:"build exited 1".into(),node_id:None,at:"failed-at".into()});let payload=dag_updated_payload("parent",&[(run,"updated".into())]);let node=&payload["runs"][0]["nodes"][0];assert_eq!(node["attempt"],2);assert_eq!(node["last_error"],json!({"code":"task_error","message":"build exited 1"}));}
#[test] fn resumed_running_run_omits_completed_at_while_settled_run_includes_it(){let(_root,mut run)=snapshot();run.completed_at=None;let active=dag_updated_payload("parent",&[(run.clone(),"updated".into())]);assert!(active["runs"][0].get("completed_at").is_none());run.status=senpi_task::dag::types::DagRunStatus::Completed;run.completed_at=Some("2026-08-14T00:00:09.000Z".into());let settled=dag_updated_payload("parent",&[(run,"updated".into())]);assert_eq!(settled["runs"][0]["completed_at"],"2026-08-14T00:00:09.000Z");}
#[test] fn paused_resume_lease_is_present_only_when_owned(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;run.lease_holder_pid=Some(4242);let held=dag_updated_payload("parent",&[(run.clone(),"updated".into())]);assert_eq!(held["runs"][0]["lease_holder_pid"],4242);run.lease_holder_pid=None;let free=dag_updated_payload("parent",&[(run,"updated".into())]);assert!(free["runs"][0].get("lease_holder_pid").is_none());}
#[test] fn plain_wire_run_preserves_existing_desktop_reducer_shape(){let(_root,mut run)=snapshot();run.nodes[0].attempt=1;let payload=dag_updated_payload("ses_parent",&[(run,"2026-08-14T00:00:01.000Z".into())]);assert_eq!(payload,json!({"parent_session_id":"ses_parent","runs":[{"run_id":"run","run_key":"key","name":"release","status":"pending","created_at":"1970-01-01T00:00:01.000Z","updated_at":"2026-08-14T00:00:01.000Z","counts":{"total":1,"pending":1,"blocked":0,"scheduled":0,"running":0,"completed":0,"failed":0,"cancelled":0,"skipped":0},"nodes":[{"id":"a","prompt":"work","depends_on":[],"state":"pending","attempt":1,"created_at":"1970-01-01T00:00:01.000Z"}],"edges":[],"waves":[{"index":0,"node_ids":["a"]}]}]}));}
